mapper.select:
select  from p_skill s
    left join p_secret sec on sec.id=s.tool_secret_id where s.id=#{skillId} and s.account_id=#{accountId}
    and s.visibility=#{visibility} and s.status!='DELETED' for update

select count(*) from p_skill where id!=#{skillId}
    and (account_id=#{accountId} or visibility='OFFICIAL') and status in ('PUBLISHED','UNLISTED')
    and tool_name=#{toolName}
